async function materializeAutomationLookupJourneyVaultCli(input: {
  automationId: string
  binDirectory: string
  commandLogPath: string
  lookupId: string
  title: string
  updatedAt: string
}): Promise<void> {
  const listEnvelope = {
    ok: true,
    data: {
      vault: '.',
      filters: {
        status: null,
        text: null,
        supportSeriesId: null,
        cursor: null,
        limit: 10,
      },
      count: 1,
      totalCount: 1,
      nextCursor: null,
      items: [{
        automationId: input.automationId,
        slug: input.lookupId,
        title: input.title,
        status: 'active',
        summary: null,
        activeUntil: null,
        schedule: {
          kind: 'dailyLocal',
          localTime: '21:00',
          timeZone: 'America/Chicago',
        },
        route: {
          channel: 'linq',
          deliveryTarget: null,
          identityId: null,
          participantId: null,
          threadId: null,
        },
        assistantTargetOverride: null,
        supportKind: 'reminder',
        plannedOccurrenceOffsetMs: null,
        contextReferences: [],
        continuityPolicy: 'preserve',
        tags: [],
        createdAt: '2026-08-09T00:00:00.000Z',
        updatedAt: input.updatedAt,
        relativePath: `bank/automations/${input.lookupId}.md`,
      }],
    },
    meta: {
      command: 'automation list',
      duration: '0ms',
    },
  }
  await mkdir(input.binDirectory, { recursive: true })
  await writeFile(input.commandLogPath, '', 'utf8')
  const executablePath = path.join(input.binDirectory, 'vault-cli')
  await writeFile(
    executablePath,
    [
      '#!/bin/sh',
      'set -eu',
      `printf '%s\\n' "$*" >> ${quoteNutritionShellLiteral(input.commandLogPath)}`,
      'case "$*" in',
      '  "automation list --format json")',
      `    printf '%s\\n' ${quoteNutritionShellLiteral(JSON.stringify(listEnvelope))}`,
      '    ;;',
      '  *)',
      '    printf \'unexpected automation lookup fixture command: %s\\n\' "$*" >&2',
      '    exit 64',
      '    ;;',
      'esac',
      '',
    ].join('\n'),
    { encoding: 'utf8', mode: 0o700 },
  )
  await chmod(executablePath, 0o700)
}

